  const fonts = count([...(css.match(/font-family:\s*([^;}{]+)/gi) || []).map((x) => x.replace(/font-family:\s*/i, "").split(",")[0].replace(/["']/g, "").trim()), ...((h.match(/fonts\.googleapis\.com\/css2?\?family=([^"'&]+)/gi) || []).map((x) => decodeURIComponent(x.split("family=")[1]).split(":")[0].replace(/\+/g, " ")))].filter((f) => f && !/inherit|sans-serif|serif|system-ui|monospace/i.test(f))).slice(0, 5).map((x) => x[0]);
